import csv,json
from pathlib import Path
from etymology_assignments import read_assignments
P=Path('curation/etymology-lab/indo-aryan-diversity-20260922');linked={r['Form_ID'] for r in read_assignments() if r['Status']=='accepted'};linked.update(r['Child_ID'] for r in csv.DictReader(open('cldf/edges.csv')) if r['Rank']=='1')
rs=[r for r in csv.DictReader(open('cldf/forms.csv')) if 'lehr' in r['Source'].split(';') and r['ID'] not in linked]
groups=[('father',['tātā'],'5754','tāta','Turner5754 gives Darrai and Wegal tatī father in the tāta family, alongside tat/tata father forms elsewhere. The source Darrai tātā belongs to this kinship-address family; retain its final ā rather than copying the comparator’s ī. The historical entry includes affectionate address to both younger and older relatives, not only the modern father sense.'),('father',['dādā'],'6261','*dādda','Turner6261 explicitly gives Pashai Gulbahar dādā father, alongside Laurowan dadā elder brother and Kurangali dādo father’s brother. Lehr gives Darrai dādā father. This is the dādda kinship family, retaining the exact Darrai sense and dialect rather than importing another dialect’s relationship label.'),('mother',['ay','ai'],'997','*āī','Turner997 explicitly gives Pashai āī mother. Both Lehr ay and ai mother records fit that existing family and are retained separately. Turner calls the head probably a nursery word and allows Dardic derivation from āryikā; this family assignment retains that uncertainty and does not assert a secure prehistoric reconstruction or identify a recent donor.')]
a=[];lines=['# Pashai Darrai: parental kinship words','','Four proposed reflex records across three families, under standing autonomous authorization.','','| # | Pashai forms and meaning | Proposed etymology | Evidence |','|---|---|---|---|']
for i,(g,fs,parent,label,ev) in enumerate(groups,1):
 hits=[r for r in rs if r['Form'] in fs and r['Gloss']==g];assert len(hits)==len(fs),(fs,hits)
 for r in hits:a.append(dict(record={k:r[k] for k in ['ID','Language_ID','Form','Gloss','Source','Tags']},parent=parent,kind='reflex',citation=r['Source']+';CDIAL['+parent+' and addenda]',evidence=ev+' Source dar lect and unmarked/marked lengths preserved; the source supplies no page locator.'))
 lines.append(f'| {i} | **{" / ".join(fs)}** ‘{g}’ ({len(hits)} records) | **{label}**, CDIAL **{parent}** | {ev} |')
reasons={'puL':'Turner8265 explicitly gives Darrai puλ son, but source puL retains an unexplained capital L through the house profile; confirm that source convention before treating it as the lateral fricative. No transcription repair.','pē':'Turner8217 lists Pashai meat forms but suggests pīvas rather than piśita for them; discriminate the two entries before assignment.','boṛēn':'Candidate9271 buḍḍha fits old better than generic vaḍra11225, but the source -ēn formation and dialect-specific history remain unchecked.','pus':'No reliable specific candidate from current homepage searches; possible contact route requires independent evidence.'}
h=[dict(record={k:r[k] for k in ['ID','Language_ID','Form','Gloss','Source','Tags']},reason=reasons[r['Form']]) for r in rs if r['Form'] in reasons]
(P/'pass048-decisions.json').write_text(json.dumps(dict(accepted=a,held=h),ensure_ascii=False,indent=2)+'\n')
selected={x['record']['Form'] for x in a+h};audit=[r for r in csv.reader(open('data/other/forms/20230705-pashai.csv')) if len(r)>3 and r[2] in selected]
(P/'pass048-source-audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n')
lines+=['',f'{len(h)} records held: son transcription convention, meat stem alternatives, old morphology, skin candidate/donor evidence. Source CSV rows retained in pass048-source-audit.json.','Research: homepage pashai-search007–009; full dictionary articles/addenda pashai-primary004–006. No source edits or new nodes.','Validation: pending.'];(P/'pass048-review.md').write_text('\n'.join(lines)+'\n');print(len(a),'accepted',len(h),'held')
